<?php
$stations=[];
foreach($sale['items'] as $item){$included=$item['bundle_components']??[];if(!$included)$included=[['name'=>$item['product_name'],'quantity'=>1,'station'=>'General']];foreach($included as $component){$station=$component['station']??'General';$stations[$station][]=['name'=>$component['name'],'quantity'=>(int)$component['quantity']*(int)$item['quantity'],'package'=>!empty($item['bundle_components'])?$item['product_name']:''];}}
$ticketEscape=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Preparation ticket #<?= (int)$sale['id'] ?></title><style>body{font:14px monospace;color:#111;margin:24px auto;max-width:360px;padding:16px}h1{font-size:21px}h2{font-size:16px;border-bottom:1px dashed;padding:10px 0}article{margin:25px 0}p{line-height:1.7}small{display:block;color:#666;margin:4px 0 14px}button{padding:10px 16px;background:#008ba8;color:white;border:0;border-radius:8px}@media print{button{display:none}article{break-inside:avoid}body{margin:0;max-width:none}}</style></head><body><button type="button" onclick="window.print()">Print ticket</button><h1>Preparation ticket</h1><p>Order #<?= (int)$sale['id'] ?><br><?= $ticketEscape($sale['branch_name']??'') ?><br><?= $ticketEscape($sale['created_at']) ?><br><?= $ticketEscape($sale['order_type']) ?></p><?php foreach($stations as $station=>$items): ?><article><h2><?= $ticketEscape($station) ?></h2><?php foreach($items as $item): ?><p><strong><?= $item['quantity'] ?> × <?= $ticketEscape($item['name']) ?></strong><?php if($item['package']): ?><small>Included in <?= $ticketEscape($item['package']) ?></small><?php endif; ?></p><?php endforeach; ?></article><?php endforeach; ?></body></html>
